<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue'
import WorkflowArtLinks from './WorkflowArtLinks.vue'
import type {WorkflowOperationProvider,WorkflowOperationRecord,WorkflowPlanTask,WorkflowPlanTasks} from './workflow-operation'
const props=defineProps<{provider:WorkflowOperationProvider;records:WorkflowOperationRecord[];projectFilter?:string;selectedId:string;projects:{id:string;name:string}[];storage:Pick<Storage,'getItem'|'setItem'|'removeItem'>|null;blocked:boolean}>()
const emit=defineEmits<{(event:'select',workflowId:string,taskId:string):void;(event:'changed'):void}>()
const data=ref<Record<string,WorkflowPlanTasks>>({}),failed=ref<string[]>([]),query=ref(''),goal=ref(''),stage=ref(''),state=ref(''),page=ref(1),size=ref(10),selectedTask=ref('')
const active=computed(()=>props.records.filter(r=>!r.management?.trashedAt&&(!props.projectFilter||r.projectId===props.projectFilter)))
const signature=computed(()=>active.value.map(r=>`${r.id}:${r.plan?.digest??''}:${r.revision}`).join('|'))
let epoch=0,loading=false,rerun=false,timer:ReturnType<typeof setInterval>|undefined
async function refresh(){if(loading){rerun=true;return}loading=true;const request=++epoch,items=[...active.value];try{const results:{id:string;result?:WorkflowPlanTasks;error?:boolean}[]=new Array(items.length);let cursor=0;await Promise.all(Array.from({length:Math.min(items.length,6)},async()=>{while(cursor<items.length){const i=cursor++,r=items[i]!;if(!r.plan){results[i]={id:r.id};continue}if(!props.provider.readPlanTasks){results[i]={id:r.id,error:true};continue}try{const result=await props.provider.readPlanTasks(r.id);if(result.workflowId!==r.id||result.planDigest!==r.plan.digest)throw Error();results[i]={id:r.id,result}}catch{results[i]={id:r.id,error:true}}}}));if(request!==epoch||items.map(r=>`${r.id}:${r.plan?.digest??''}:${r.revision}`).join('|')!==signature.value)return;const next:Record<string,WorkflowPlanTasks>={};const errors:string[]=[];for(const x of results)if(x.result)next[x.id]=x.result;else if(x.error)errors.push(x.id);data.value=next;failed.value=errors}finally{loading=false;if(rerun){rerun=false;void refresh()}}}
watch(signature,()=>{epoch++;void refresh()},{immediate:true})
onMounted(()=>{timer=setInterval(()=>void refresh(),15000)})
onBeforeUnmount(()=>{epoch++;if(timer)clearInterval(timer)})
const rows=computed(()=>active.value.flatMap(r=>{const p=data.value[r.id];if(!p||p.planDigest!==r.plan?.digest)return [];return p.tasks.map(t=>({goal:r,task:t,stage:r.management?.stages.find(s=>s.taskRefs.some(x=>x.planDigest===p.planDigest&&x.taskId===t.taskId))}))}))
const filtered=computed(()=>rows.value.filter(x=>(!goal.value||x.goal.id===goal.value)&&(!stage.value||`${x.goal.id}:${x.stage?.id}`===stage.value)&&(!state.value||x.task.executionState===state.value)&&(!query.value||`${x.task.text} ${x.goal.presentation?.title??''} ${x.task.taskId}`.toLowerCase().includes(query.value.trim().toLowerCase()))))
const pageRows=computed(()=>filtered.value.slice((page.value-1)*size.value,page.value*size.value))
watch([query,goal,stage,state,size],()=>page.value=1)
watch(filtered,x=>page.value=Math.min(page.value,Math.max(1,Math.ceil(x.length/size.value))))
const labels:Record<string,string>={'not-started':'未开始',unknown:'待核对',starting:'启动待确认',queued:'排队',running:'执行中','pause-requested':'请求暂停',paused:'已暂停',resuming:'恢复待确认',completed:'执行完成',failed:'失败',accepted:'执行范围已验收'}
const countScope=computed(()=>rows.value.filter(x=>(!goal.value||x.goal.id===goal.value)&&(!stage.value||`${x.goal.id}:${x.stage?.id}`===stage.value)&&(!query.value||`${x.task.text} ${x.goal.presentation?.title??''} ${x.task.taskId}`.toLowerCase().includes(query.value.trim().toLowerCase()))))
const acceptedLabel=(task:WorkflowPlanTask)=>task.acceptanceScope==='task-directory'?'任务目录已验收':task.acceptanceScope==='technical-sample'?'技术样例已验收':'执行范围已验收，具体范围待核对'
const counts=computed(()=>Object.fromEntries(Object.keys(labels).map(k=>[k,countScope.value.filter(x=>x.task.executionState===k).length])))
const selectedRow=computed(()=>rows.value.find(x=>selectedTask.value===`${x.goal.id}:${x.task.taskId}`))
function choose(workflowId:string,taskId:string){selectedTask.value=`${workflowId}:${taskId}`;emit('select',workflowId,taskId)}
</script>
<template>
 <section aria-label="计划任务列表" class="task-list"><h3>计划任务</h3><p>任务来自当前计划；任务目录验收不等于产品完成。</p>
 <div class="filters"><label>搜索<input v-model="query" placeholder="任务或目标"></label><label>目标<select v-model="goal"><option value="">全部目标</option><option v-for="r in active" :key="r.id" :value="r.id">{{ r.presentation?.title||r.id }}</option></select></label><label>阶段<select v-model="stage"><option value="">全部阶段</option><template v-for="r in active" :key="r.id"><option v-for="s in r.management?.stages??[]" :key="r.id+':'+s.id" :value="r.id+':'+s.id">{{ r.presentation?.title||r.id }} / {{ s.title }}</option></template></select></label><label>状态<select v-model="state"><option value="">全部状态</option><option v-for="(label,key) in labels" :key="key" :value="key">{{ label }}</option></select></label></div>
 <p>执行中 {{ counts.running }} · 执行完成 {{ counts.completed }} · 执行范围已验收 {{ counts.accepted }} · 待核对 {{ counts.unknown }}</p><p v-if="failed.length" role="alert">部分目标任务读取失败或服务未提供任务接口，状态待核对。</p><p v-if="active.some(r=>data[r.id]?.readiness!=='fresh'&&r.plan)" role="status">部分任务的依赖审阅尚未完成、已过期或不可用；不能据此启动。</p><p v-if="active.some(r=>data[r.id]?.unboundRuns)" role="status">存在未关联任务的历史执行，不能推定所属任务。</p>
 <table><thead><tr><th>任务</th><th>目标</th><th>阶段</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="x in pageRows" :key="x.goal.id+':'+x.task.taskId"><td>{{ x.task.text }}</td><td>{{ x.goal.presentation?.title||x.goal.id }}</td><td>{{ x.stage?.title||'未分阶段' }}</td><td>{{ x.task.executionState==='accepted'?acceptedLabel(x.task):labels[x.task.executionState] }}</td><td><button type="button" :aria-current="selectedTask===x.goal.id+':'+x.task.taskId?'true':undefined" @click="choose(x.goal.id,x.task.taskId)">查看任务</button></td></tr><tr v-if="!pageRows.length"><td colspan="5">暂无可核验的计划任务。</td></tr></tbody></table><el-pagination v-model:current-page="page" v-model:page-size="size" :page-sizes="[10,20,50]" :total="filtered.length" layout="total, sizes, prev, pager, next" />
 <section v-if="selectedRow" aria-label="所选计划任务"><h4>{{ selectedRow.task.text }}</h4><p>任务进度：{{ labels[selectedRow.task.executionState] }}；{{ selectedRow.task.acceptance==='accepted'?acceptedLabel(selectedRow.task):selectedRow.task.acceptance==='unknown'?'验收待核对':'尚未确认任务目录验收' }}。</p><p v-if="selectedRow.task.executionState==='unknown'">阻塞原因：执行归属或结果待核对。</p><p v-else-if="selectedRow.task.executionState==='failed'">阻塞原因：执行失败，请查看执行详情。</p><p v-else-if="selectedRow.task.executionState==='paused'">阻塞原因：任务已暂停，请先核对依赖。</p><WorkflowArtLinks :key="selectedRow.goal.id+':'+selectedRow.goal.plan?.digest+':'+selectedRow.task.taskId" :provider="provider" :record="selectedRow.goal" :task="selectedRow.task" :projects="projects" :storage="storage" :blocked="blocked" @changed="emit('changed')" /></section>
 </section>
</template>
<style scoped>.filters{display:flex;gap:12px;flex-wrap:wrap}.filters label{display:grid;gap:4px}table{width:100%;border-collapse:collapse}th,td{text-align:left;border-bottom:1px solid var(--el-border-color);padding:8px}input,select{font:inherit;padding:8px;max-width:100%}</style>
